// ═══════════════════════════════════════════════════════════════════════
//  THE ONLY NODE YOU EDIT. One { … } block per scheduled briefing.
// ═══════════════════════════════════════════════════════════════════════
//
//  ⚠️ EACH FIRING COSTS ONE AGENTIC TURN. That is intended here — you are
//     asking an agent to actually go and do work — but it is why this list
//     should hold briefings, not watchers. Anything of the form "check if X
//     happened" belongs in mail_watch / web_publish_watch instead, where the
//     check is free and only a real hit costs anything.
//
//  id       REQUIRED, stable. Used to remember "already fired today".
//  at       REQUIRED, 'HH:MM' in the timezone below.
//  days     '*' or weekday numbers, 1=Mon … 7=Sun. E.g. '1,2,3,4,5' or '7'.
//  on       'YYYY-MM-DD' for a ONE-SHOT that fires on that date only, then
//           never again. Delete the entry afterwards; leaving it is harmless.
//  dom      Day of month, '1'..'31', for monthly runs. Ignored when `on` is set.
//  agent    Who runs it, in whose voice it arrives. Default 'speda'.
//  intent   REQUIRED. What the agent should DO — written as an instruction to
//           itself. Be specific about which tools to use; a vague intent gets
//           a vague briefing.
//  gym_days Optional, e.g. '1,3,5' (Mon/Wed/Fri). When set, the FACTS block
//           appended to the intent states plainly whether today and tomorrow
//           are gym days. Set this rather than describing the schedule in
//           prose: a model asked to work out 'is today a gym day' will
//           sometimes get it wrong, and a calendar never does.
//  mode     'push' (delivered to Telegram, the default) or 'silent' (runs and
//           is stored, nothing is sent — good for indexing or bookkeeping).
//
const TZ = 'Europe/Istanbul';

const BRIEFINGS = [

  {
    id: 'morning_brief',
    at: '08:00',
    days: '*',
    agent: 'speda',
    mode: 'push',
    intent: "GÜNLÜK SABAH BRIEFİNGİ — bu bir iş akışıdır, GERÇEK araçlarla çalıştır.\n\nÖNCE VERİYİ TOPLA. Bu adımların hiçbirini owner'a anlatma, sadece yap:\n1. use_toolset ile google_gmail'i yükle → son 24 saatin mailleri.\n2. use_toolset ile google_calendar'ı yükle → bugün ve önümüzdeki 3 gün.\n3. news_deep_dive (country='tr') → son 24 saatin haberleri.\n4. system_info (metric=all) → disk, bellek, uptime.\n\nSONRA BRIEFING'İ YAZ. Bu bir pano değil, bir rapordur: başlıklar ve madde listeleri yerine akıcı Türkçe paragraflar.\n\n- İLK CÜMLE owner'ın bugün karar vermesi gereken tek şeydir. Öyle bir şey yoksa bunu söyle ve geç (\"sakin bir sabah\") — uydurma bir aciliyet yaratma.\n- SAYIYI DEĞİL ANLAMINI yaz. \"Enflasyon %31,75\" veridir; \"kira artış tavanı %31,9, yenileme bu orandan gider\" analizdir. Analize ulaşamıyorsan veriyi de yazma.\n- SADECE İSTİSNAYI RAPORLA. Sunucu sağlıklıysa tek cümle ya da hiç. Takvim hafta boyu aynıysa dört kez tekrarlama — \"vardiya hafta boyu sabit, tek değişken çarşamba ve cuma akşamı\" de.\n- HABER FİLTRESİ: owner'ın parasına, sağlığına, işine veya güvenliğine dokunmayan haber YAZILMAZ. Popüler olması yetmez. En fazla 2-4 haber.\n- MAİL: önemli olanı yaz, gerisini tek cümlede topla (\"kalanı bülten ve kargo bildirimi\").\n- HANGİ ARACI KULLANDIĞINI, hangisinin boş döndüğünü, sırada ne yapacağını ASLA yazma. Bir kaynak hiç çalışmadıysa en sonda tek sade cümle: \"haber akışı bugün sessiz.\"\n- YAPMADIĞIN ŞEYİ YAPTIM DEME. \"Sentinel'e işlettim\", \"sayfayı açtım\", \"hatırlatma kurdum\" — sadece o aracı bu turda GERÇEKTEN çağırdıysan. Çağırmadıysan teklif et: \"istersen Sentinel'e işleteyim.\"\n- ELİNDE OLMAYAN VERİYİ UYDURMA. Kira tutarı, sözleşme tarihi, hava durumu, yol süresi — bunları bir araç ya da hafıza vermediyse o cümleyi hiç kurma. Yuvarlak bir tahmin, yazılmamış cümleden daha kötüdür.\n- Sonda kısa bir teklifle kapat.\n\nUzunluk: 150-200 kelime. Sesli okunduğunda takip edilebilmeli.\nYazdığın metin owner'a otomatik push olarak iletilir — send_telegram_message ÇAĞIRMA.",
  },

  {
    id: 'news_briefing',
    at: '07:30',
    days: '*',
    agent: 'nightcrawler',
    mode: 'push',
    intent: "GÜNLÜK GÜNDEM BRİFİNGİ — bu bir iş akışıdır, GERÇEK araçlarla çalıştır.\n\nÖNCE VERİYİ TOPLA. Adımları owner'a anlatma, sadece yap:\n1. news_headlines(since_hours=24) çağır — RSS deposundaki başlıklar bu turun ana kaynağıdır, ilk ve varsayılan adım budur.\n2. Bir haber gerçekten önemliyse ve doğrulama, geçmiş ya da ilgili gelişme gerektiriyorsa EN FAZLA 1-2 news_deep_dive çağrısı yap. Sıradan bir başlık için asla çağırma — bütçe sınırlı ve paylaşımlı.\n3. news_watch listesindeki izlenen kelimelere değen bir şey varsa öne çıkar.\n\nSONRA GÜNDEMİ YAZ. Bu bir liste dökümü değil, bir brifingdir:\n- Kategoriye göre grupla: Türkiye, dünya, ekonomi, teknoloji/siber — sadece dolu olan kategorileri yaz.\n- Her haber TEK cümle: ne oldu ve neden önemli. Başlığı olduğu gibi kopyalama, kendi cümlenle özetle.\n- İzlenen kelimelerle eşleşen haberler en başta.\n- Önem sırala, kronolojik sıralama değil. Magazin ya da owner'ı ilgilendirmeyen haberi atla — popüler olması yetmez.\n- news_headlines boş ya da sessizse tek cümlede söyle: bugün akışta önemli bir şey yok. Uydurma haber yazma.\n- Hangi aracı çağırdığını, kaç haber döndüğünü ya da hangi kaynaktan geldiğini asla yazma — sadece gündemi anlat.\n- Elinde olmayan detayı (kaynak linki, tam rakam, spekülasyon) uydurma.\n\nUzunluk: 150-220 kelime, akıcı Türkçe.\nYazdığın metin owner'a otomatik push olarak iletilir — send_telegram_message ÇAĞIRMA.",
  },

  {
    id: 'atomix_health',
    at: '08:00',
    days: '*',
    agent: 'atomix',
    mode: 'push',
    intent: "GÜNLÜK SAĞLIK BRIEFİNGİ — bu bir iş akışıdır, GERÇEK araçlarla çalıştır.\n\nVERİYİ ÇEK: health_data aracını live=true ile çağır. Bu, telefondan taze senkron ister ve veri bayatsa sana sayı VERMEZ, hata döner.\n  metrics: ['sleep_session','heart_rate','resting_heart_rate','steps'], range: '7d', live: true\n7 gün istiyoruz çünkü tek bir gecenin sayısı, geçmiş hafta olmadan hiçbir şey ifade etmez — hafta baseline'dır, dün konudur.\n\nARAÇ \"REFUSED\" DÖNERSE: BRIEFING BUDUR. Hangi metriğin ne zamandan beri gelmediğini söyle; saatin takılı ve eşleşmiş olduğunu, Speda GO'da Health sekmesinin canlı göründüğünü kontrol etmesini öner. Eski sayıları ASLA bugünün verisiymiş gibi yazma, \"en son şu veri var\" diye de sunma. Bu eksik bir briefing değil, doğru briefingdir.\n\nVERİ GELDİYSE — bu da bir pano değil, bir rapordur:\n\n- İLK İKİ CÜMLE \"iyi miyim?\" sorusunu cevaplar. Her şey normal aralıktaysa bunu söyle ve bitir; üç cümlelik briefing geçerli briefingdir.\n- HER SAYI KENDİ BASELINE'IYLA GELİR. \"Nabız 98\" hiçbir şey demektir; \"nabız 98, senin normalin 62-64\" her şey demektir. Baseline'ı 7 günlük veriden çıkar.\n- METRİK METRİK DEĞİL, GÜN GÜN ANLAT. Uyku, nabız ve adım aynı haftanın üç görüntüsüdür; aralarındaki örüntüyü kur (toparlanma → yük → durgunluk gibi).\n- TEŞHİSİ SEN DARALT. \"Cihaz hatası mı, stres mi, hastalık mı?\" diye owner'a sorma — elindeki diğer metriklerle şıkları ele, sonra geriye kalan TEK ayırt edici soruyu sor.\n- SADECE İNSANIN BİLDİĞİNİ SOR. Nasıl hissettiği senin ölçemediğin bir veridir; briefingi onunla kapat.\n- EKSİK VERİ BÖLÜM DEĞİL DİPNOTTUR: en sonda tek cümle, muhtemel sebebiyle.\n- SAMPLE SAYISI, TABLO ADI, \"şu metrik dönmedi\" gibi şeyleri ASLA yazma. Bir veriye güvenmiyorsan bir kez \"bu ölçüme güvenmiyorum\" de ve geç.\n- TAKVİM VE GYM PROGRAMI SENİN ALANIN DEĞİL (o Speda'da). Senin katkın \"bugün ağır antrenman değil, yürüyüş\" gibi bir ÖNERİDİR — programın kendisi değil.\n- KIRMIZI ÇİZGİ: gün boyuna yayılmış nabız yükselmesi baseline'ın 25+ bpm üstündeyse ya da üç günden uzun sürüyorsa, tavsiye vermeyi bırak ve doktora görünmesini söyle.\n\nUzunluk: 120-180 kelime, akıcı Türkçe.\nYazdığın metin owner'a otomatik push olarak iletilir — send_telegram_message ÇAĞIRMA.",
  },

  {
    id: 'atomix_evening',
    at: '23:00',
    gym_days: '1,3,5',   // Mon/Wed/Fri — computed below, never inferred
    // 23:00, not 20:00. The old standalone workflow's cron said '0 20', but
    // n8n was reading it as UTC, so it had always fired at 23:00 Istanbul —
    // and 23:00 is the time the owner actually wants. Fixing the timezone
    // silently moved it three hours earlier; this puts it back.
    days: '*',
    agent: 'atomix',
    // 'silent' because the reminders tool does the delivering, with answer
    // buttons attached. On 'push' the reply would ALSO be pushed and the
    // owner would get the same checklist twice, once unanswerable.
    mode: 'silent',
    intent: "EVENING REMINDER — bu Atomix'in kişisel hatırlatmasıdır ve owner'ın ONAYLAMASI gerekir.\n\nAşağıdaki GERÇEKLER bölümü sana hangi günde olduğunu ve gym durumunu SÖYLER. Günü, haftanın gününü veya gym gününü KENDİN HESAPLAMA, ÇIKARIM YAPMA — sadece aşağıda yazanı kullan. Orada yazmayan bir şeyi varsayma.\n\nMesajın içeriği:\n1. 150 mg Lustral al — HER GÜN, istisnasız.\n2. 5 g kreatin al — HER GÜN, istisnasız.\n3. Spor salonu giriş kartını al — SADECE yarın gym günüyse. Değilse bu maddeyi hiç yazma.\n4. Yarınki antrenman için spor çantanı hazırla — SADECE yarın gym günüyse. Değilse bu maddeyi hiç yazma.\n\nTon ve ek not:\n- Bugün gym günüyse: 'bugün antrenman yaptın' diyebilirsin. Gym günü DEĞİLSE bunu ASLA yazma — owner bugün antrenman yapmadı.\n- Yarın gym günüyse: çanta ve kart vurgusunu güçlendir.\n- Ne bugün ne yarın gym günü değilse: sadece ilaç ve kreatini hatırlat, kısa tut.\n- Hafta sonuysa daha rahat bir ton kullan.\nMesajı Atomix'in sesiyle yaz — doğal, kısa, ilgilendiğini gösteren. Statik metin gibi olmasın.\n\nSONRA — ve bu kritik — mesajı `reminders` aracıyla gönder:\n  action='ask', reminder_id='atomix_evening', text=<yazdığın mesaj>,\n  options=['✅ Hepsini yaptım', '⏭️ Bugün atlıyorum'],\n  every_minutes=5, max_asks=10\n\nBu araç mesajı butonlarla gönderir ve owner cevaplayana kadar 5 dakikada bir TEKRAR sorar. send_telegram_message ÇAĞIRMA ve mesajı sadece cevap olarak yazma — tek gönderim yolu bu araçtır. Araç 'already_open' derse ikinci bir mesaj gönderme.",
  },

  {
    id: 'gym_renewal',
    at: '08:00',
    on: '2026-07-29',       // one-shot: fires on this date only
    agent: 'sentinel',
    mode: 'push',
    intent: "GYM RENEWAL REMINDER. Today is July 29 — the owner's gym membership renewal day. Send a concise push notification reminding him: 'Gym membership yenileme günü — bugün 29 Temmuz. Yenileme işlemini tamamla.' Your reply auto-delivers as a push to the owner — do NOT call send_telegram_message. Keep it short.",
  },

  // Was inactive as a standalone workflow — uncomment to switch it on.
  // { id: 'monthly_finance', at: '09:00', dom: '1', agent: 'sentinel', mode: 'push',
  //   intent: "Remind Ahmet to provide current month's expenses and income data for finance review and logging. Ask for specific amounts and categorize them properly for the finance records." },

];

// ── Nothing below this line needs editing ───────────────────────────────
// "Already fired today" lives in the workflow's static data, so a briefing
// fires ONCE at its time rather than on every tick for the rest of the day.
const store = $getWorkflowStaticData('global');
const fired = store.fired || {};
// How late a briefing's FIRST-EVER firing may be. A briefing this list has
// never seen before is only run if it came due within this window; one that
// went by hours ago is recorded as done instead. That covers both cases that
// would otherwise fire a stale briefing on the spot: activating the workflow
// in the afternoon, and adding a new 08:00 entry to a running one.
const GRACE_MIN = 15;

// Read the clock in the configured zone explicitly rather than trusting the
// container's TZ — that assumption is exactly what made every schedule in this
// system three hours out.
const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, hour12: false,
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', weekday: 'short',
}).formatToParts(new Date()).reduce((a, p) => (a[p.type] = p.value, a), {});

const today = `${parts.year}-${parts.month}-${parts.day}`;
const nowMin = Number(parts.hour) * 60 + Number(parts.minute);
const dowNum = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 }[parts.weekday];

const out = [];
BRIEFINGS.forEach(b => {
  if (!b || !b.id || !b.at || !b.intent) { return; }
  if (fired[b.id] === today) { return; }                       // already ran today
  if (b.on) {
    if (today !== String(b.on)) { return; }                   // one-shot, wrong day
  } else {
    if (b.dom && Number(b.dom) !== Number(parts.day)) { return; }        // monthly
    const days = String(b.days || '*');
    if (days !== '*' && !days.split(',').map(s => s.trim()).includes(String(dowNum))) { return; }
  }
  const [hh, mm] = String(b.at).split(':').map(Number);
  const dueMin = hh * 60 + mm;
  if (nowMin < dueMin) { return; }                             // not yet

  const firstSight = fired[b.id] === undefined;
  fired[b.id] = today;
  if (firstSight && nowMin - dueMin > GRACE_MIN) { return; }   // seed, don't retro-fire
  // ── FACTS ─────────────────────────────────────
  // Anything a calendar can settle is settled HERE, not by the model.
  // Atomix once told the owner 'you trained today, tomorrow is a rest day'
  // on a Tuesday, having worked the day out from a prose description of the
  // schedule. Deterministic input, prose output — never the reverse.
  const NL = String.fromCharCode(10);
  const TR_DAYS = ['', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar'];
  const tomorrowDow = (dowNum % 7) + 1;
  let facts = NL + NL + '— DEĞİŞMEZ GERÇEKLER (hesaplama, aynen kullan) —'
            + NL + 'Bugün: ' + today + ', ' + TR_DAYS[dowNum] + '.'
            + NL + 'Yarın: ' + TR_DAYS[tomorrowDow] + '.';
  if (b.gym_days) {
    const gym = String(b.gym_days).split(',').map(s => s.trim());
    const todayGym = gym.includes(String(dowNum));
    const tmrGym = gym.includes(String(tomorrowDow));
    facts += NL + 'Bugün gym günü: ' + (todayGym ? 'EVET' : 'HAYIR') + '.'
           + NL + 'Yarın gym günü: ' + (tmrGym ? 'EVET' : 'HAYIR') + '.'
           + NL + (tmrGym ? 'Kart ve çanta maddelerini YAZ.'
                          : 'Kart ve çanta maddelerini YAZMA.');
  }

  out.push({ json: {
    id: b.id,
    agent: (b.agent || 'speda').trim(),
    intent: b.intent + facts,
    mode: b.mode === 'silent' ? 'silent' : 'push',
    at: b.at,
  }, pairedItem: { item: 0 } });
});

store.fired = fired;
return out;
